                                    viewer.scrollDownByFraction(
                                        if (webtoonFraction > 0f) webtoonFraction else PHRASE_FINAL_STEP,
                                    )
                                is eu.kanade.tachiyomi.ui.reader.viewer.pager.PagerViewer ->
