package eu.kanade.tachiyomi.data.ocr

internal data class OcrScanQueueEntry(
    val chapterId: Long,
    val state: State,
    val lastError: String? = null,
) {
    enum class State {
        QUEUED,
        SCANNING,
        ERROR,
    }
}

internal data class OcrScanQueueState(
    val entries: List<OcrScanQueueEntry>,
    val activeProgress: OcrChapterScanProgress?,
    val isPaused: Boolean,
) {
    val isActive: Boolean
        get() = entries.isNotEmpty()

    val activeEntry: OcrScanQueueEntry?
        get() = entries.firstOrNull { it.state == OcrScanQueueEntry.State.SCANNING }

    val activeChapterId: Long?
        get() = activeEntry?.chapterId

    val hasQueuedEntries: Boolean
        get() = entries.any { it.state == OcrScanQueueEntry.State.QUEUED }

    val remainingChapterCount: Int
        get() = entries.count { it.state != OcrScanQueueEntry.State.ERROR }
}

internal data class OcrChapterScanCacheEvent(
    val chapterId: Long,
    val hasResults: Boolean,
)

internal data class OcrScanStoreSnapshot(
    val entries: List<OcrScanQueueEntry>,
    val isPaused: Boolean,
)

internal fun OcrScanStoreSnapshot.toQueueState(
    activeProgress: OcrChapterScanProgress? = null,
): OcrScanQueueState {
    return OcrScanQueueState(
        entries = entries,
        activeProgress = activeProgress?.takeIf { progress ->
            entries.any { entry ->
                entry.chapterId == progress.chapterId &&
                    entry.state == OcrScanQueueEntry.State.SCANNING
            }
        },
        isPaused = isPaused,
    )
}

internal fun OcrScanQueueState.toStoreSnapshot(): OcrScanStoreSnapshot {
    return OcrScanStoreSnapshot(
        entries = entries,
        isPaused = isPaused,
    )
}

package eu.kanade.tachiyomi.data.ocr

import android.content.Context
import androidx.core.app.NotificationCompat
import eu.kanade.tachiyomi.R
import eu.kanade.tachiyomi.data.notification.NotificationReceiver
import eu.kanade.tachiyomi.data.notification.Notifications
import eu.kanade.tachiyomi.util.system.cancelNotification
import eu.kanade.tachiyomi.util.system.notificationBuilder
import eu.kanade.tachiyomi.util.system.notify
import tachiyomi.core.common.i18n.pluralStringResource
import tachiyomi.core.common.i18n.stringResource
import tachiyomi.i18n.MR

internal class OcrScanNotifier(
    private val context: Context,
) {
    private val progressNotificationBuilder by lazy {
        context.notificationBuilder(Notifications.CHANNEL_OCR_PROGRESS) {
            setOnlyAlertOnce(true)
            setAutoCancel(false)
        }
    }

    private val errorNotificationBuilder by lazy {
        context.notificationBuilder(Notifications.CHANNEL_OCR_ERROR) {
            setAutoCancel(true)
        }
    }

    private fun NotificationCompat.Builder.show(id: Int) {
        context.notify(id, build())
    }

    fun onProgress(
        progress: OcrChapterScanProgress,
        remainingChapters: Int,
    ) {
        with(progressNotificationBuilder) {
            setSmallIcon(android.R.drawable.stat_sys_download)
            setAutoCancel(false)
            setContentTitle("${progress.mangaTitle} - ${progress.chapterName}")
            setContentText(
                context.stringResource(
                    MR.strings.ocr_preprocess_progress,
                    progress.chapterName,
                    progress.processedPages,
                    progress.totalPages,
                ),
            )
            setSubText(
                context.pluralStringResource(
                    MR.plurals.download_queue_summary,
                    count = remainingChapters,
                    remainingChapters,
                ),
            )
            setProgress(progress.totalPages, progress.processedPages, false)
            setOngoing(true)
            setContentIntent(NotificationReceiver.openEntryPendingActivity(context, progress.mangaId))
            show(Notifications.ID_OCR_PROGRESS)
        }
    }

    fun onComplete(progress: OcrChapterScanProgress) {
        with(progressNotificationBuilder) {
            setSmallIcon(R.drawable.ic_done_24dp)
            setAutoCancel(true)
            setContentTitle(context.stringResource(MR.strings.ocr_preprocess_title))
            setContentText(context.stringResource(MR.strings.ocr_preprocess_completed, progress.chapterName))
            setSubText(progress.mangaTitle)
            setProgress(0, 0, false)
            setOngoing(false)
            setContentIntent(NotificationReceiver.openEntryPendingActivity(context, progress.mangaId))
            show(Notifications.ID_OCR_PROGRESS)
        }
    }

    fun onError(
        error: OcrChapterScanError,
    ): String {
        val message = error.failure.toMessage()
        with(errorNotificationBuilder) {
            setSmallIcon(R.drawable.ic_warning_white_24dp)
            setContentTitle(context.stringResource(MR.strings.ocr_preprocess_failed, error.chapterName))
            setContentText(message)
            setSubText(error.mangaTitle)
            setProgress(0, 0, false)
            error.mangaId?.let { setContentIntent(NotificationReceiver.openEntryPendingActivity(context, it)) }
            show(Notifications.ID_OCR_ERROR)
        }
        return message
    }

    fun dismissProgress() {
        context.cancelNotification(Notifications.ID_OCR_PROGRESS)
    }

    private fun OcrScanFailure.toMessage(): String {
        return when (this) {
            OcrScanFailure.ChapterNotFound -> context.stringResource(MR.strings.chapter_not_found)
            OcrScanFailure.MangaNotFound -> context.stringResource(MR.strings.ocr_scan_manga_not_found)
            OcrScanFailure.NoPages -> context.stringResource(MR.strings.page_list_empty_error)
            is OcrScanFailure.Unexpected ->
                message
                    ?: context.stringResource(MR.strings.download_notifier_unknown_error)
        }
    }
}

package mihon.domain.ocr.interactor

import mihon.domain.ocr.model.OcrImage
import mihon.domain.ocr.model.OcrPageResult
import mihon.domain.ocr.model.OcrRegion
import mihon.domain.ocr.repository.OcrRepository

class ScanPageOcr(
    private val ocrRepository: OcrRepository,
) {
    /**
     * [onPartial] — области по мере их распознавания, см.
     * [OcrRepository.scanPage]. Позволяет озвучивать первые реплики страницы,
     * пока движок ещё читает последние.
     *
     * [cacheResult] = false для кадров авточтения: они не страницы (см.
     * [OcrRepository.scanPage]).
     */
    suspend fun await(
        chapterId: Long,
        pageIndex: Int,
        image: OcrImage,
        onPartial: ((OcrRegion) -> Unit)? = null,
        cacheResult: Boolean = true,
    ): OcrPageResult {
