private fun frameTag(geometry: OcrFrameGeometry?): String {
    if (geometry == null) return "full"
    val scroll = (geometry.scrollFraction * 64).toInt().coerceIn(0, 64)
    val top = geometry.crop?.let { (it.top * 64).toInt().coerceIn(0, 64) } ?: -1
